window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _lm = SLP.books.find(function(b){ return b.id === "lam"; });
if (!_lm) throw new Error("data/canon.js must load before ot-29-lam-ezek-a.js");
(_lm.chapters = _lm.chapters || []).push(
  { n:1, summary:"Jerusalem sits solitary, once full of people, now like a widow; once a princess among the provinces, now paying tribute. She weeps in the night with tears on her cheeks, and among all her former allies there is none to comfort her; the friends she trusted have become her enemies. Judah has gone into captivity because of affliction and great servitude, finding no rest among the heathen. The city's gates are desolate, the solemn feasts have stopped, and her priests sigh. The poem is honest about the cause: the LORD has afflicted her for the multitude of her transgressions. The people trade their pleasant things for food, enemies mock at her sabbaths, and foreigners entered her sanctuary. From the depths she confesses that the LORD is righteous and she has rebelled, and she asks God to behold her sorrow and deal with her enemies as He has dealt with her.",
    context:"An anonymous grief poem over Jerusalem after its fall; Jewish and Christian tradition have long connected the book with the prophet Jeremiah, though the text itself names no author.",
    keyVerses:[
      { ref:"Lamentations 1:1", text:"How doth the city sit solitary, that was full of people! how is she become as a widow! she that was great among the nations, and princess among the provinces, how is she become tributary!" },
      { ref:"Lamentations 1:12", text:"Is it nothing to you, all ye that pass by? behold, and see if there be any sorrow like unto my sorrow, which is done unto me, wherewith the LORD hath afflicted me in the day of his fierce anger." },
      { ref:"Lamentations 1:18", text:"The LORD is righteous; for I have rebelled against his commandment: hear, I pray you, all people, and behold my sorrow: my virgins and my young men are gone into captivity." }
    ],
    takeaway:"Grief becomes honest before God when we admit, The LORD is righteous, and our own rebellion caused the wound.",
    quiz:[
      { q:"How is Jerusalem described in the opening verse of Lamentations?", choices:["A radiant bride awaiting her bridegroom","A widow sitting solitary, once full of people","An unconquered fortress feared by all nations","A merchant city grown rich on trade"], a:1, why:"Verse 1 asks how the city sits solitary that was full of people, become as a widow and now tributary." },
      { q:"According to this chapter, why did Jerusalem suffer these things?", choices:["Her armies were simply outnumbered by a stronger empire","Her allies broke their treaties without any cause on her part","The LORD afflicted her for the multitude of her transgressions","Foreign merchants corrupted her economy over many years"], a:2, why:"Verse 5 says her adversaries prosper because the LORD hath afflicted her for the multitude of her transgressions, and verse 8 adds that Jerusalem hath grievously sinned." },
      { q:"What confession does the poem put in Jerusalem's mouth in verse 18?", choices:["The LORD is righteous; for I have rebelled against his commandment","The LORD has dealt with me more harshly than I deserve","My punishment came by chance, not from the LORD","My enemies alone are guilty for what happened"], a:0, why:"Verse 18 confesses that the LORD is righteous because the speaker has rebelled against His commandment, then asks all people to behold her sorrow." }
    ] },
  { n:2, summary:"The Lord Himself is the actor in this poem: He has covered the daughter of Zion with a cloud in his anger, swallowed up her strong holds, drawn back his right hand, and bent his bow like an enemy. He has violently taken away his tabernacle as if it were of a garden, caused the solemn feasts and sabbaths to be forgotten in Zion, cast off his altar, abhorred his sanctuary, and stretched out a line to destroy the wall. Her king and princes are among the Gentiles, the law is no more, and her prophets find no vision from the LORD. The elders sit on the ground in silence with dust on their heads. Passersby clap and hiss: Is this the city men called the perfection of beauty? The Lord has done what He devised and fulfilled His word of old. The answer to all this is not despair but prayer: arise, cry out in the night, and pour out your heart like water before Him.",
    context:"A poet's account of Jerusalem's fall, describing the destruction as the Lord acting in anger to fulfill the word He had commanded in the days of old.",
    keyVerses:[
      { ref:"Lamentations 2:5", text:"The Lord was as an enemy: he hath swallowed up Israel, he hath swallowed up all her palaces: he hath destroyed his strong holds, and hath increased in the daughter of Judah mourning and lamentation." },
      { ref:"Lamentations 2:17", text:"The LORD hath done that which he had devised; he hath fulfilled his word that he had commanded in the days of old: he hath thrown down, and hath not pitied: and he hath caused thine enemy to rejoice over thee, he hath set up the horn of thine adversaries." },
      { ref:"Lamentations 2:19", text:"Arise, cry out in the night: in the beginning of the watches pour out thine heart like water before the face of the Lord:" }
    ],
    takeaway:"God keeps His word in judgment as surely as in promise; even then He invites us to pour out our hearts to Him by night.",
    quiz:[
      { q:"In Lamentations 2, the Lord is described as acting toward Jerusalem like what?", choices:["A shepherd seeking lost sheep","A refiner purifying silver","An enemy bending his bow","A physician tending wounds"], a:2, why:"Verse 4 says he bent his bow like an enemy and slew all that were pleasant to the eye, and verse 5 says the Lord was as an enemy." },
      { q:"Why do passersby hiss and clap, asking, Is this the city that men call The perfection of beauty?", choices:["The city's fall was so complete that its former glory astonished them","The city had always been plain and unimpressive","They mistook Jerusalem for some other ruined city","They were celebrating a festival in the streets"], a:0, why:"Verse 15 shows onlookers stunned that the famed city could lie so ruined, and verse 17 explains the LORD had fulfilled the word He commanded in the days of old." },
      { q:"What had Jerusalem's prophets done before the fall, according to verse 14?", choices:["They warned the kings to repent and were ignored","They led the people in faithful national fasting","They hid the law because it was banned","They saw vain and foolish things and never exposed her iniquity"], a:3, why:"Verse 14 says thy prophets have seen vain and foolish things for thee and have not discovered thine iniquity, to turn away thy captivity." }
    ] },
  { n:3, summary:"The speaker calls himself the man that hath seen affliction by the rod of God's wrath and lists the blows: darkness instead of light, broken bones, a hedge he cannot escape, heavy chains, prayers shut out, a bear and a lion lying in wait, arrows from the quiver, wormwood and gall, gravel between his teeth. His strength and hope seem gone. Then comes the turning point: this I recall to my mind, therefore have I hope. It is of the LORD's mercies that we are not consumed; His compassions fail not, they are new every morning, and great is His faithfulness. The LORD is his portion; it is good to hope and quietly wait for the salvation of the LORD, for He will not cast off for ever and does not afflict willingly. Then the call: let us search and try our ways, and turn again to the LORD. The chapter ends with the memory of crying from the low dungeon and the answer, Fear not.",
    context:"The central chapter of the book: one speaker describes personal affliction under God's hand and then turns the people's grief toward hope in the Lord's mercy.",
    keyVerses:[
      { ref:"Lamentations 3:22", text:"It is of the LORD's mercies that we are not consumed, because his compassions fail not." },
      { ref:"Lamentations 3:23", text:"They are new every morning: great is thy faithfulness." },
      { ref:"Lamentations 3:40", text:"Let us search and try our ways, and turn again to the LORD." }
    ],
    takeaway:"Because the LORD's compassions fail not and are new every morning, hope is possible in the very middle of grief.",
    quiz:[
      { q:"In Lamentations 3, the afflicted speaker says God was unto him like which two animals lying in wait?", choices:["A wolf and a serpent","A leopard and a jackal","An eagle and a vulture","A bear and a lion"], a:3, why:"Verse 10 says He was unto me as a bear lying in wait, and as a lion in secret places." },
      { q:"What turns the speaker's despair into hope in the middle of the chapter?", choices:["News that the siege had been lifted","Recalling that the LORD's mercies and compassions fail not","A promise that his enemies would soon repent","Forgetting the afflictions he had suffered"], a:1, why:"Verse 21 says, This I recall to my mind, therefore have I hope, and verses 22-23 explain that His compassions fail not and are new every morning." },
      { q:"What does the chapter urge God's people to do with their suffering?", choices:["Deny that anything is truly wrong","Take revenge on those who caused it","Let us search and try our ways, and turn again to the LORD","Wait passively without praying at all"], a:2, why:"Verse 40 calls for searching and trying our ways and turning again to the LORD, while verses 25-26 add quietly seeking and waiting for His salvation." }
    ] },
  { n:4, summary:"The gold has become dim, the most fine gold changed, and the sanctuary's stones lie poured out in the streets. Zion's precious sons are now esteemed as earthen pitchers, the work of the potter. Famine has turned even natural affection upside down: young children ask for bread and no man breaks it to them, and those who ate delicately are desolate in the streets. The Nazarites, once purer than snow, are withered; the chapter notes starkly that dying by the sword was better than dying by hunger. The Lord accomplished His fury and kindled a fire in Zion. Kings of the earth would never have believed an enemy could enter Jerusalem's gates, yet her prophets and priests had shed the blood of the just in her midst, and she had watched for a nation that could not save. To daughter Edom: your cup will pass to you too. To daughter Zion: your punishment is accomplished; He will no more carry you into captivity.",
    context:"A comparison of Jerusalem before and after the siege, addressed at the close to daughter Zion and to daughter Edom, dwelling in the land of Uz.",
    keyVerses:[
      { ref:"Lamentations 4:1", text:"How is the gold become dim! how is the most fine gold changed! the stones of the sanctuary are poured out in the top of every street." },
      { ref:"Lamentations 4:12", text:"The kings of the earth, and all the inhabitants of the world, would not have believed that the adversary and the enemy should have entered into the gates of Jerusalem." },
      { ref:"Lamentations 4:22", text:"The punishment of thine iniquity is accomplished, O daughter of Zion; he will no more carry thee away into captivity: he will visit thine iniquity, O daughter of Edom; he will discover thy sins." }
    ],
    takeaway:"No past glory or reputation shields a people from corrupted worship's consequences, but God Himself appoints where punishment ends.",
    quiz:[
      { q:"What image opens Lamentations 4?", choices:["The gold has become dim","The lamp has gone out","The harvest has failed","The river has run dry"], a:0, why:"Verse 1 asks, How is the gold become dim! how is the most fine gold changed! with the sanctuary's stones poured out in the streets." },
      { q:"Why would the kings of the earth not have believed the enemy could enter Jerusalem's gates?", choices:["Jerusalem's walls were the tallest in the world","Her sin, including the blood shed by her prophets and priests, made what seemed impossible happen","No enemy army had ever reached that region before","God had promised the city would never see war"], a:1, why:"Verses 12-13 say the kings would not have believed it, and verse 13 gives the cause: the sins of her prophets and the iniquities of her priests, that have shed the blood of the just." },
      { q:"What does verse 22 declare about Zion's punishment?", choices:["It will continue for a thousand generations","It now depends on Edom's repentance","It was never actually carried out","It is accomplished, and He will no more carry her into captivity"], a:3, why:"Verse 22 says the punishment of thine iniquity is accomplished, O daughter of Zion; he will no more carry thee away into captivity, while Edom's iniquity will be visited." }
    ] },
  { n:5, summary:"The book ends with a communal prayer: remember, O LORD, what is come upon us. The survivors list what they have lost — inheritance turned to strangers, children left orphans, mothers become widows, water and wood bought with money, necks under persecution, bread won at the peril of their lives. Their fathers sinned and are gone, and the children bear the iniquities. Princes are hanged, young men are taken to grind, elders have ceased from the gate, music and joy have stopped, and the crown has fallen from their head: woe unto us, for we have sinned. Foxes walk on the desolate mountain of Zion. Against that darkness stands one great fact: Thou, O LORD, remainest for ever; thy throne from generation to generation. So the prayer makes its central petition: Turn thou us unto thee, O LORD, and we shall be turned; renew our days as of old. Even the raw closing line is still addressed to God, prayer pressed onward in hope.",
    context:"The book's closing communal prayer, spoken by the survivors of Jerusalem's fall, who ask the Lord to turn their hearts back to Him and renew their days.",
    keyVerses:[
      { ref:"Lamentations 5:16", text:"The crown is fallen from our head: woe unto us, that we have sinned!" },
      { ref:"Lamentations 5:19", text:"Thou, O LORD, remainest for ever; thy throne from generation to generation." },
      { ref:"Lamentations 5:21", text:"Turn thou us unto thee, O LORD, and we shall be turned; renew our days as of old." }
    ],
    takeaway:"Restoration begins with the prayer, Turn thou us unto thee — for the LORD remains enthroned forever while everything else falls.",
    quiz:[
      { q:"According to Lamentations 5, what did the people have to do to get water and wood?", choices:["Draw them from their own wells and groves","Trade their gold to traveling merchants","Send servants on long journeys to fetch them","Buy the water with money and buy the wood sold to them"], a:3, why:"Verse 4 says, We have drunken our water for money; our wood is sold unto us." },
      { q:"What is the central petition of this closing prayer?", choices:["Turn thou us unto thee, O LORD, and we shall be turned","Deliver us from Babylon without any delay","Give us back our houses and vineyards","Punish our enemies more than you punished us"], a:0, why:"Verse 21 pleads, Turn thou us unto thee, O LORD, and we shall be turned; renew our days as of old." },
      { q:"What anchor does the prayer find before it asks to be restored?", choices:["The memory of Israel's military victories","The promise that the nations will soon perish","The truth that Thou, O LORD, remainest for ever","The hope that the temple stones still stood"], a:2, why:"Verse 19 confesses, Thou, O LORD, remainest for ever; thy throne from generation to generation, immediately before the plea of verse 21." }
    ] }
);
